Here is the root cause:
The bug occurs because when `IFF_XMIT_DST_RELEASE` is cleared and `napi_tx` is disabled (use_napi=false), the virtio_net driver does not drop the skb's dst reference (`skb_dst_drop`) before queuing the skb in the transmit ring. Consequently, the skb retains a reference to a `dst_entry` whose `dst_ops` structure may be freed if the network namespace is destroyed while the skb is still pending. Later, when `free_old_xmit()` calls `dst_release()` on the stale skb, it accesses the freed `dst_ops`, causing a use-after-free (UAF). The missing explicit dst release in the non-napi path is the root cause.

Here is the patch:

 static netdev_tx_t start_xmit(struct sk_buff *skb, struct net_device *dev)
 {
 	struct virtnet_info *vi = netdev_priv(dev);
 	int qnum = skb_get_queue_mapping(skb);
 	struct send_queue *sq = &vi->sq[qnum];
 	int err;
 	struct netdev_queue *txq = netdev_get_tx_queue(dev, qnum);
 	bool xmit_more = netdev_xmit_more();
 	bool use_napi = sq->napi.weight;
 	bool kick;

 	if (!use_napi)
 		free_old_xmit(sq, txq, false);
 	else
 		virtqueue_disable_cb(sq->vq);

 	/* timestamp packet in software */
 	skb_tx_timestamp(skb);

 	/* Try to transmit */
 	err = xmit_skb(sq, skb, !use_napi);

 	/* This should not happen! */
 	if (unlikely(err)) {
 		DEV_STATS_INC(dev, tx_fifo_errors);
 		if (net_ratelimit())
 			dev_warn(&dev->dev,
 				 "Unexpected TXQ (%d) queue failure: %d\n",
 				 qnum, err);
 		DEV_STATS_INC(dev, tx_dropped);
 		dev_kfree_skb_any(skb);
 		return NETDEV_TX_OK;
 	}

 	/* Don't wait up for transmitted skbs to be freed. */
 	if (!use_napi) {
 		skb_orphan(skb);
+		skb_dst_drop(skb);
 		nf_reset_ct(skb);
 	}

 	if (use_napi)
 		tx_may_stop(vi, dev, sq);
 	else
 		check_sq_full_and_disable(vi, dev,sq);

 	kick = use_napi ? __netdev_tx_sent_queue(txq, skb->len, xmit_more) :
 			  !xmit_more || netif_xmit_stopped(txq);
 	if (kick) {
 		if (virtqueue_kick_prepare(sq->vq) && virtqueue_notify(sq->vq)) {
 			u64_stats_update_begin(&sq->stats.syncp);
 			u64_stats_inc(&sq->stats.kicks);
 			u64_stats_update_end(&sq->stats.syncp);
 		}
 	}

 	if (use_napi && kick && unlikely(!virtqueue_enable_cb_delayed(sq->vq)))
 		virtqueue_napi_schedule(&sq->napi, sq->vq);

 	return NETDEV_TX_OK;
 }



